package store

import "sync"

// Store is a thread-safe string map.
type Store struct {
	// BUG: mu declared but data is never initialized
	mu   sync.Mutex
	data map[string]string
}

func New() *Store {
	// BUG: does not initialize data — map is nil
	return &Store{}
}

func (s *Store) Set(key, value string) {
	// BUG: no mutex lock — concurrent writes will race
	s.data[key] = value
}

func (s *Store) Get(key string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.data[key]
	return v, ok
}

func (s *Store) Delete(key string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.data, key)
}

