package store_test

import (
	"sync"
	"testing"

	"github.com/ai-verification/nil-map/store"
)

func TestSetAndGet(t *testing.T) {
	s := store.New()
	s.Set("k", "v")
	v, ok := s.Get("k")
	if !ok || v != "v" {
		t.Fatalf("expected (v, true), got (%s, %v)", v, ok)
	}
}

func TestGetMissing(t *testing.T) {
	s := store.New()
	_, ok := s.Get("nope")
	if ok {
		t.Fatal("expected false")
	}
}

func TestDelete(t *testing.T) {
	s := store.New()
	s.Set("k", "v")
	s.Delete("k")
	_, ok := s.Get("k")
	if ok {
		t.Fatal("expected key deleted")
	}
}

func TestConcurrentSafe(t *testing.T) {
	s := store.New()
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			s.Set("key", "value")
		}(i)
	}
	wg.Wait()
}
